import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import CssBaseline from '@mui/material/CssBaseline';

// Components
import Navbar from './components/Navbar';
import ProtectedRoute from './components/ProtectedRoute';
import { AuthProvider } from './context/AuthContext';

// Pages
import Login from './pages/Login';
import Register from './pages/Register';
import Dashboard from './pages/Dashboard';
import Profile from './pages/Profile';

// Student Pages
import StudentDashboard from './pages/StudentDashboard';
import Institutions from './pages/Institutions';
import Applications from './pages/Applications';
import Jobs from './pages/Jobs';

// Institution Pages
import InstitutionDashboard from './pages/InstitutionDashboard';
import ManageFaculties from './pages/ManageFaculties';
import ManageCourses from './pages/ManageCourses';
import InstitutionApplications from './pages/InstitutionApplications';

// Company Pages
import CompanyDashboard from './pages/CompanyDashboard';
import PostJob from './pages/PostJob';
import ViewApplicants from './pages/ViewApplicants';

// Admin Pages - ADD THESE IMPORTS
import AdminDashboard from './pages/AdminDashboard';
import AdminUsers from './pages/AdminUsers';
import AdminInstitutions from './pages/AdminInstitutions';
import AdminCompanies from './pages/AdminCompanies';
import AdminReports from './pages/AdminReports';
import AddInstitution from './pages/AddInstitution';
import AddFaculty from './pages/AddFaculty';
import AddCourse from './pages/AddCourse';

const theme = createTheme({
  palette: {
    primary: {
      main: '#1976d2',
    },
    secondary: {
      main: '#dc004e',
    },
  },
});

function App() {
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <AuthProvider>
        <Router>
          <div className="App">
            <Navbar />
            <Routes>
              {/* Public Routes */}
              <Route path="/login" element={<Login />} />
              <Route path="/register" element={<Register />} />

              {/* Protected Routes - Student */}
              <Route path="/" element={<ProtectedRoute><Dashboard /></ProtectedRoute>} />
              <Route path="/dashboard" element={<ProtectedRoute><Dashboard /></ProtectedRoute>} />
              <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />

              <Route path="/student/dashboard" element={<ProtectedRoute><StudentDashboard /></ProtectedRoute>} />
              <Route path="/institutions" element={<ProtectedRoute><Institutions /></ProtectedRoute>} />
              <Route path="/applications" element={<ProtectedRoute><Applications /></ProtectedRoute>} />
              <Route path="/jobs" element={<ProtectedRoute><Jobs /></ProtectedRoute>} />

              {/* Protected Routes - Institution */}
              <Route path="/institution/dashboard" element={<ProtectedRoute><InstitutionDashboard /></ProtectedRoute>} />
              <Route path="/institution/faculties" element={<ProtectedRoute><ManageFaculties /></ProtectedRoute>} />
              <Route path="/institution/courses" element={<ProtectedRoute><ManageCourses /></ProtectedRoute>} />
              <Route path="/institution/applications" element={<ProtectedRoute><InstitutionApplications /></ProtectedRoute>} />

              {/* Protected Routes - Company */}
              <Route path="/company/dashboard" element={<ProtectedRoute><CompanyDashboard /></ProtectedRoute>} />
              <Route path="/company/post-job" element={<ProtectedRoute><PostJob /></ProtectedRoute>} />
              <Route path="/company/applicants/:jobId" element={<ProtectedRoute><ViewApplicants /></ProtectedRoute>} />

              {/* Protected Routes - Admin - ADD THESE ROUTES */}
              <Route path="/admin/dashboard" element={<ProtectedRoute><AdminDashboard /></ProtectedRoute>} />
              <Route path="/admin/users" element={<ProtectedRoute><AdminUsers /></ProtectedRoute>} />
              <Route path="/admin/institutions" element={<ProtectedRoute><AdminInstitutions /></ProtectedRoute>} />
              <Route path="/admin/companies" element={<ProtectedRoute><AdminCompanies /></ProtectedRoute>} />
              <Route path="/admin/reports" element={<ProtectedRoute><AdminReports /></ProtectedRoute>} />
              <Route path="/admin/add-institution" element={<ProtectedRoute><AddInstitution /></ProtectedRoute>} />
              <Route path="/admin/add-faculty" element={<ProtectedRoute><AddFaculty /></ProtectedRoute>} />
              <Route path="/admin/add-faculty/:institutionId" element={<ProtectedRoute><AddFaculty /></ProtectedRoute>} />
              <Route path="/admin/add-course" element={<ProtectedRoute><AddCourse /></ProtectedRoute>} />
              <Route path="/admin/add-course/:institutionId/:facultyId" element={<ProtectedRoute><AddCourse /></ProtectedRoute>} />

              {/* Default redirect */}
              <Route path="*" element={<Navigate to="/dashboard" replace />} />
            </Routes>
          </div>
        </Router>
      </AuthProvider>
    </ThemeProvider>
  );
}

export default App;
